-- O relatório do Yazo não traz id: o casamento com a agenda é pelo nome da sessão.
-- Os títulos abaixo são os do relatório, byte a byte (inclusive os espaços duplos),
-- para que o match por nome funcione sem heurística de normalização.

update summit_2026.sessions s set titulo = v.titulo, atualizado_em = now()
from (values
  ('d1-0900-abertura', 'Abertura'),
  ('d1-1130-conversas-dificeis', 'Conversas difíceis, times que crescem: Como transformar tensão em diálogo, aprendizagem e colaboração'),
