  ('d1-1130-mensurar-intervir', 'Mensurar, intervir, provar: a metodologia Oxford para wellbeing como ativo de performance'),
  ('d1-1130-produtividade-sustentavel', 'Produtividade sustentável: Como manter performance sem esgotar pessoas'),
  ('d1-1130-sustenta-equipes', 'O que sustenta equipes de alta performance: Ferramentas de inteligência relacional para líderes'),
