  ('d1-1500-tres-movimentos', 'Os três movimentos do líder que destravam aprendizagem coletiva'),
  ('d1-1530-trabalho-anos', 'Trabalho S/A: O que 26 anos ouvindo líderes revelam sobre carreira, gestão e o futuro do trabalho'),
  ('d1-1600-consciencia-finitude', 'Como a consciência da finitude transforma a forma de viver e as escolhas que fazemos'),
  ('d1-1600-curadoria', 'Saúde mental não é igual para todos:  Como trazer a diversidade para a conversa'),
  ('d1-1600-relacoes-sustentam', 'Relações que sustentam: A importância dos vínculos para a saúde emocional, financeira e no trabalho'),
  ('d1-1720-lideranca-consciente', 'Liderança Consciente: Autorregulação, pausa e autocompaixão na liderança'),
