  ('d2-1500-desalinhamentos-burnout', 'Os 6 desalinhamentos do burnout: Como ler e redesenhar o trabalho do seu time'),
  ('d2-1500-infraestrutura-performance', 'Infraestrutura de Performance: Desenho pessoal para executivos sob pressão crônica'),
  ('d2-1500-lider-arquiteto', 'O líder como arquiteto do trabalho: Rotinas para dar clareza, remover obstáculos e sustentar a performance'),
